/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Dashboard Page Header" (boardui.com/templates/dashboard).
 * No BoardUI source was used.
 */
'use client';

import type { ComponentType, HTMLAttributes, ReactNode } from 'react';
import { RiNotification3Line } from '@remixicon/react';
import { Breadcrumb, BreadcrumbItem } from '@/components/motion/breadcrumb';
import { IconButton } from '@/components/motion/icon-button';
import { cx, sortCx } from '@/lib/cx';

/**
 * DashboardPageHeader: the strip at the top of every BoardUI dashboard page.
 *
 *   Board team › Mertcan › Home                      (breadcrumb, 12px)
 *   Welcome Mertcan        [range] [bell] [Export] [+ Create ticket]
 *
 * The breadcrumb takes plain data: a crumb can carry initials (drawn in a
 * 16px tinted circle, like the team and person crumbs in the shot) or an
 * icon, and the last crumb is the current page. The toolbar is three slots
 * in a fixed order: a date-range control, the notification bell, then the
 * actions, so every page lines them up the same way. Below `sm` the toolbar
 * wraps under the title instead of squeezing it.
 */

type IconComponent = ComponentType<{ className?: string; 'aria-hidden'?: boolean | 'true' | 'false' }>;

export type CrumbTone = 'blue' | 'neutral' | 'lime' | 'purple';

export interface PageHeaderCrumb {
  label: string;
  href?: string;
  onPress?: () => void;
  /** One or two letters in a 16px circle (a team, workspace or person). */
  initials?: string;
  tone?: CrumbTone;
  /** A 16px glyph before the label, e.g. the page's nav icon. */
  icon?: IconComponent;
}

export interface DashboardPageHeaderProps extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  title: ReactNode;
  description?: ReactNode;
  /** Ancestors first; the last crumb is the current page. */
  breadcrumbs?: readonly PageHeaderCrumb[];
  breadcrumbLabel?: string;
  /** Date-range control shown first in the toolbar, e.g. `<PeriodStepper>`. */
  dateRange?: ReactNode;
  /** Unread count for the built-in bell. Omit (and `notifications`) to hide the bell. */
  notificationCount?: number;
  onNotificationsPress?: () => void;
  notificationsLabel?: string;
  /** Replaces the built-in bell, e.g. a bell that opens a notification popover. */
  notifications?: ReactNode;
  /** Trailing buttons: secondary actions first, the primary action last. */
  actions?: ReactNode;
  /** Heading level of the title. Default 1. */
  headingLevel?: 1 | 2 | 3;
}

const styles = sortCx({
  initials: {
    base: 'inline-flex size-4 shrink-0 items-center justify-center rounded-full text-[9px] leading-none font-semibold uppercase',
    tone: {
      blue: 'bg-status-blue-background text-status-blue-text',
      neutral: 'bg-background-tertiary-default text-text-secondary',
      lime: 'bg-status-lime-background text-status-lime-text',
      purple: 'bg-status-purple-background text-status-purple-text',
    },
  },
  badge: [
    'pointer-events-none absolute top-1 start-[18px] flex h-3.5 min-w-3.5 items-center justify-center rounded-full px-[3px]',
    'bg-red-600 text-[10px] leading-none font-semibold text-white tabular-nums ring-2 ring-background-primary-default',
    'origin-center transition-[scale,opacity] duration-200 ease-out motion-reduce:transition-none',
  ].join(' '),
});

export interface PageHeaderBellProps {
  count?: number;
  /** Counts above this show as `max+`. Default 9. */
  max?: number;
  label?: string;
  onPress?: () => void;
  className?: string;
}

/** The header's bell: IconButton plus a red count badge that scales away at zero. */
export function PageHeaderBell({ count = 0, max = 9, label = 'Notifications', onPress, className }: PageHeaderBellProps) {
  const shown = count > max ? `${max}+` : String(count);
  return (
    <span className={cx('relative inline-flex shrink-0', className)}>
      <IconButton icon={RiNotification3Line} aria-label={count > 0 ? `${label}, ${count} unread` : label} onClick={onPress} />
      <span aria-hidden className={cx(styles.badge, count > 0 ? 'scale-100 opacity-100' : 'scale-50 opacity-0')}>
        {count > 0 ? shown : null}
      </span>
    </span>
  );
}

function CrumbInitials({ initials, tone = 'neutral' }: { initials: string; tone?: CrumbTone }) {
  return (
    <span aria-hidden className={cx(styles.initials.base, styles.initials.tone[tone])}>
      {initials.slice(0, 2)}
    </span>
  );
}

// #region critical
export function DashboardPageHeader({
  title,
  description,
  breadcrumbs = [],
  breadcrumbLabel = 'Breadcrumb',
  dateRange,
  notificationCount,
  onNotificationsPress,
  notificationsLabel,
  notifications,
  actions,
  headingLevel = 1,
  className,
  ...props
}: DashboardPageHeaderProps) {
  const Heading = (['h1', 'h2', 'h3'] as const)[headingLevel - 1] ?? 'h1';
  const bell =
    notifications ??
    (notificationCount !== undefined ? (
      <PageHeaderBell count={notificationCount} label={notificationsLabel} onPress={onNotificationsPress} />
    ) : null);
  const hasToolbar = Boolean(dateRange || bell || actions);
  const lastIndex = breadcrumbs.length - 1;

  return (
    <header {...props} className={cx('flex w-full min-w-0 flex-col gap-4', className)}>
      {breadcrumbs.length > 0 ? (
        <Breadcrumb aria-label={breadcrumbLabel} className="-mx-1">
          {breadcrumbs.map((crumb, index) => (
            <BreadcrumbItem
              key={`${index}-${crumb.label}`}
              icon={crumb.initials ? undefined : crumb.icon}
              href={index === lastIndex ? undefined : crumb.href}
              onClick={index === lastIndex ? undefined : crumb.onPress}
              current={index === lastIndex}
            >
              {crumb.initials ? <CrumbInitials initials={crumb.initials} tone={crumb.tone} /> : null}
              {crumb.label}
            </BreadcrumbItem>
          ))}
        </Breadcrumb>
      ) : null}

      <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <Heading className="truncate text-title-2-medium text-text-primary">{title}</Heading>
          {description ? <p className="text-body-regular text-text-secondary">{description}</p> : null}
        </div>
        {hasToolbar ? (
          <div className="flex flex-wrap items-center gap-2">
            {dateRange}
            {bell}
            {actions}
          </div>
        ) : null}
      </div>
    </header>
  );
}
// #endregion

/*
 * Built for Kinetic from scratch after the public preview of BoardUI's "Dashboard Page Header" (boardui.com/templates/dashboard).
 * No BoardUI source was used.
 */
'use client';

import { useState } from 'react';
import { endOfMonth, type CalendarDate, type DateDuration } from '@internationalized/date';
import { useDateFormatter } from 'react-aria';
import { RiArrowLeftSLine, RiArrowRightSLine } from '@remixicon/react';
import { cx } from '@/lib/cx';

/**
 * PeriodStepper: the dashboard's "< 29 Jun - 5 Jul >" control. A bordered
 * pill with a previous and next button around the formatted range. Each
 * press shifts the whole window by its own length, so a 7-day window walks
 * week by week and a calendar month walks month by month (end clamped to the
 * month's last day). The label is an <output>, so screen readers hear the
 * new range after each step.
 */

export interface PeriodRange {
  start: CalendarDate;
  end: CalendarDate;
}

export interface PeriodStepperProps {
  value?: PeriodRange;
  defaultValue?: PeriodRange;
  onChange?: (range: PeriodRange) => void;
  /** Fixed shift per press. Defaults to the range's own length (or its month count for whole months). */
  step?: DateDuration;
  /** Earliest allowed start; the previous button disables once a step would cross it. */
  minValue?: CalendarDate;
  /** Latest allowed end; the next button disables once a step would cross it. */
  maxValue?: CalendarDate;
  /** Intl options for the label. Default `{ day: 'numeric', month: 'short' }`. */
  formatOptions?: Intl.DateTimeFormatOptions;
  /** 36px (default, matches Button) or 32px (card headers). */
  size?: 'medium' | 'small';
  'aria-label'?: string;
  previousLabel?: string;
  nextLabel?: string;
  className?: string;
}

const MS_PER_DAY = 86_400_000;

function lengthInDays(range: PeriodRange) {
  return Math.round((range.end.toDate('UTC').getTime() - range.start.toDate('UTC').getTime()) / MS_PER_DAY) + 1;
}

/** Whole calendar months (1st of a month through the last day of a month): the month count, else 0. */
function wholeMonths(range: PeriodRange) {
  if (range.start.day !== 1 || range.end.compare(endOfMonth(range.end)) !== 0) return 0;
  return (range.end.year - range.start.year) * 12 + range.end.month - range.start.month + 1;
}

// #region critical
/** Moves a range one window back (-1) or forward (+1). */
export function shiftPeriod(range: PeriodRange, direction: 1 | -1, step?: DateDuration): PeriodRange {
  if (step) {
    const signed = Object.fromEntries(
      Object.entries(step).map(([unit, amount]) => [unit, (amount ?? 0) * direction]),
    ) as DateDuration;
    return { start: range.start.add(signed), end: range.end.add(signed) };
  }
  const months = wholeMonths(range);
  if (months > 0) {
    // Adding months to the 31st clamps (Jan 31 + 1 month = Feb 28) and the
    // clamp then sticks (Feb 28 + 1 month = Mar 28), so rebuild the end from
    // the new start instead of shifting it.
    const start = range.start.add({ months: months * direction });
    return { start, end: endOfMonth(start.add({ months: months - 1 })) };
  }
  const days = lengthInDays(range) * direction;
  return { start: range.start.add({ days }), end: range.end.add({ days }) };
}

/** The localized "Jun 29 – Jul 5" label for a range (UTC, so it never drifts a day). */
export function usePeriodLabel(range: PeriodRange, formatOptions?: Intl.DateTimeFormatOptions) {
  const formatter = useDateFormatter({ day: 'numeric', month: 'short', ...formatOptions, timeZone: 'UTC' });
  return formatter.formatRange(range.start.toDate('UTC'), range.end.toDate('UTC'));
}

export function PeriodStepper({
  value,
  defaultValue,
  onChange,
  step,
  minValue,
  maxValue,
  formatOptions,
  size = 'medium',
  'aria-label': ariaLabel = 'Date range',
  previousLabel = 'Previous period',
  nextLabel = 'Next period',
  className,
}: PeriodStepperProps) {
  const [uncontrolled, setUncontrolled] = useState<PeriodRange | undefined>(defaultValue);
  const range = value ?? uncontrolled;
  if (!range) throw new Error('PeriodStepper needs `value` or `defaultValue`.');

  const previous = shiftPeriod(range, -1, step);
  const next = shiftPeriod(range, 1, step);
  const canGoBack = !minValue || previous.start.compare(minValue) >= 0;
  const canGoForward = !maxValue || next.end.compare(maxValue) <= 0;
  const label = usePeriodLabel(range, formatOptions);

  const commit = (nextRange: PeriodRange) => {
    setUncontrolled(nextRange);
    onChange?.(nextRange);
  };

  const buttonClass = cx(
    'inline-flex shrink-0 cursor-pointer items-center justify-center rounded-lg text-foreground-icon-primary outline-none',
    'transition-colors duration-150 ease-out motion-reduce:transition-none',
    'hover:bg-background-primary-hover focus-visible:ring-2 focus-visible:ring-border-focus-ring',
    'disabled:cursor-not-allowed disabled:text-foreground-icon-disabled disabled:hover:bg-transparent',
    size === 'small' ? 'size-6' : 'size-7',
  );

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className={cx(
        'inline-flex items-center gap-0.5 rounded-2lg border border-border-button-default bg-background-primary-default shadow-xs',
        size === 'small' ? 'h-8 px-[3px]' : 'h-9 px-[3px]',
        className,
      )}
    >
      <button type="button" aria-label={previousLabel} disabled={!canGoBack} onClick={() => commit(previous)} className={buttonClass}>
        <RiArrowLeftSLine aria-hidden className="size-4 rtl:rotate-180" />
      </button>
      <output
        aria-live="polite"
        className={cx(
          'min-w-0 px-1.5 text-center whitespace-nowrap tabular-nums text-text-primary',
          size === 'small' ? 'text-body-2-medium' : 'text-body-medium',
        )}
      >
        {label}
      </output>
      <button type="button" aria-label={nextLabel} disabled={!canGoForward} onClick={() => commit(next)} className={buttonClass}>
        <RiArrowRightSLine aria-hidden className="size-4 rtl:rotate-180" />
      </button>
    </div>
  );
}
// #endregion
